import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.CHi0mXvr.js";var i=JSON.parse(`{"title":"Meeting Checklist and Procedure","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","frontmatter":{"title":"Meeting Checklist and Procedure","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban Introduction, Scrumban Concept, What is Scrumban, Scrumban vs Kanban, Agile Methodology, Agile Framework, Kanban Methodology, Scrum Methodology, Scrumban Process, Scrumban Operation Guide, Scrumban Board, WIP Limit, Workflow Management, How to use Kanban Board, Scrumban Advantages, Scrumban Features, Scrumban Effects, Scrumban Use Cases, Scrumban Introduction Effects, Scrumban Jira Setup, Scrumban Board Template, Scrumban Tool, Scrumban Collaboration Tool, Scrumban Workflow, Agile Project Management, Work Efficiency Methodology, Iterative Work Management, Bottleneck Resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/activity.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/agile/checklistAndProcedure.html"}]],"sort":450},"headers":[],"relativePath":"en/agile/checklistAndProcedure.md","filePath":"en/agile/checklistAndProcedure.md","lastUpdated":1786257982000}`),a={name:`en/agile/checklistAndProcedure.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="scrumban-meeting-and-event-list-and-detailed-procedures" tabindex="-1">Scrumban Meeting and Event List and Detailed Procedures <a class="header-anchor" href="#scrumban-meeting-and-event-list-and-detailed-procedures" aria-label="Permalink to “Scrumban Meeting and Event List and Detailed Procedures”">​</a></h1><h2 id="_1-daily-stand-up" tabindex="-1">1. <strong>Daily Stand-up</strong> <a class="header-anchor" href="#_1-daily-stand-up" aria-label="Permalink to “1. Daily Stand-up”">​</a></h2><ul><li><strong>Purpose</strong>: For team members to share their current work status, identify obstacles, and clarify the goals for the day.</li><li><strong>How to proceed</strong>: <ul><li>Held daily at a set time (usually in the morning) for within 15 minutes.</li><li>All team members stand during the meeting to keep it short.</li><li>Each team member briefly shares answers to these 3 questions: <ul><li>What did you do yesterday?</li><li>What are you planning to do today?</li><li>Are there any obstacles in your current work?</li></ul></li><li>Conducted in front of the Kanban board to visually check the progress of tasks.</li></ul></li></ul><h2 id="_2-backlog-refinement" tabindex="-1">2. <strong>Backlog Refinement</strong> <a class="header-anchor" href="#_2-backlog-refinement" aria-label="Permalink to “2. Backlog Refinement”">​</a></h2><ul><li><strong>Purpose</strong>: The process of continuously reviewing and reprioritizing backlog items, and breaking them down into task units.</li><li><strong>How to proceed</strong>: <ul><li>Conducted periodically (e.g., 1-2 times a week).</li><li>The PO (Product Owner) or related person in charge participates to adjust the priority of stories.</li><li>Analyze items with the team and, if necessary, break down the work into smaller units.</li><li>Increase understanding and readiness for the work to prevent disruptions in future work.</li></ul></li></ul><h2 id="_3-release-planning" tabindex="-1">3. <strong>Release Planning</strong> <a class="header-anchor" href="#_3-release-planning" aria-label="Permalink to “3. Release Planning”">​</a></h2><ul><li><strong>Purpose</strong>: Setting mid-to-long-term goals and establishing functional release plans.</li><li><strong>How to proceed</strong>: <ul><li>Conducted as needed or periodically (e.g., monthly, quarterly).</li><li>The entire team participates to discuss target features and release schedules.</li><li>Create a plan by appropriately combining the Kanban board and Scrum&#39;s sprint concept.</li><li>Establish a realistic schedule considering the Work in Progress (WIP) limits.</li></ul></li></ul><h2 id="_4-review-meeting" tabindex="-1">4. <strong>Review Meeting</strong> <a class="header-anchor" href="#_4-review-meeting" aria-label="Permalink to “4. Review Meeting”">​</a></h2><ul><li><strong>Purpose</strong>: A time to share completed work outcomes and receive feedback.</li><li><strong>How to proceed</strong>: <ul><li>Conducted periodically or as needed.</li><li>Team members demonstrate completed work or share results.</li><li>Stakeholders and PO attend to provide feedback.</li><li>Discuss areas for improvement and success stories together.</li></ul></li></ul><h2 id="_5-retrospective" tabindex="-1">5. <strong>Retrospective</strong> <a class="header-anchor" href="#_5-retrospective" aria-label="Permalink to “5. Retrospective”">​</a></h2><ul><li><strong>Purpose</strong>: To look back on the team&#39;s work process and collaboration methods to derive areas for improvement.</li><li><strong>How to proceed</strong>: <ul><li>Conducted periodically (e.g., once every 2 weeks, or once a month).</li><li>All team members participate.</li><li>General procedure: <ul><li>Share what went well</li><li>Identify problems and obstacles</li><li>Discuss improvement ideas</li><li>Select actionable action items</li></ul></li><li>Action items are reflected and executed in the next period.</li></ul></li></ul><h2 id="_6-priority-adjustment-and-wip-limit-management-meeting" tabindex="-1">6. <strong>Priority Adjustment and WIP Limit Management Meeting</strong> <a class="header-anchor" href="#_6-priority-adjustment-and-wip-limit-management-meeting" aria-label="Permalink to “6. Priority Adjustment and WIP Limit Management Meeting”">​</a></h2><ul><li><strong>Purpose</strong>: To optimize workflow by checking the WIP limit, which is the core of Kanban, and adjusting priorities.</li><li><strong>How to proceed</strong>: <ul><li>Can be conducted frequently as needed.</li><li>Check if the team has exceeded the current WIP limit.</li><li>Identify bottlenecks or delayed situations and discuss solutions.</li><li>Readjust priorities when adding tasks.</li></ul></li></ul><hr><h1 id="additional-notes" tabindex="-1">Additional Notes <a class="header-anchor" href="#additional-notes" aria-label="Permalink to “Additional Notes”">​</a></h1><ul><li><strong>Utilization of Kanban Board</strong>: The core of all meetings is to proceed centered around the Kanban board (physical board or digital board) to visualize the work.</li><li><strong>Flexible Progression</strong>: Scrumban does not have strict sprints, and the frequency and content of meetings can be adjusted as needed.</li><li><strong>Importance of WIP Limits</strong>: Strictly adhering to WIP limits is important for improving work efficiency and minimizing bottlenecks.</li></ul><hr>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};